from fastapi import APIRouter, HTTPException, status
from pydantic import BaseModel, Field
from typing import List, Optional
from datetime import datetime, timezone

router = APIRouter(prefix="/api/inventorys", tags=["Inventorys"])

class InventoryCreate(BaseModel):
    name: str = Field(..., min_length=2, max_length=100)
    status: str = Field(default="active", pattern="^(active|pending|archived)$")
    metadata_info: Optional[str] = ""

class InventoryResponse(InventoryCreate):
    id: int
    created_at: str

db_inventorys: List[dict] = []

@router.post("", response_model=InventoryResponse, status_code=status.HTTP_201_CREATED)
def create_inventory(item: InventoryCreate):
    record = {
        "id": len(db_inventorys) + 1,
        "name": item.name,
        "status": item.status,
        "metadata_info": item.metadata_info,
        "created_at": datetime.now(timezone.utc).isoformat()
    }
    db_inventorys.append(record)
    return record

@router.get("/{item_id}", response_model=InventoryResponse)
def get_inventory(item_id: int):
    for r in db_inventorys:
        if r["id"] == item_id:
            return r
    raise HTTPException(status_code=404, detail="Inventory not found")

